describe('Checkout Flow', () => {
    beforeEach(() => {
        cy.visit('/checkout');
    });

    it('should complete the checkout flow in order (happy path)', () => {
        cy.get('#cart').should('be.visible');
        cy.get('#proceed-to-checkout').click();

        cy.url().should('include', '/checkout/details');
        cy.get('#name').type('John Doe');
        cy.get('#address').type('123 Main St');
        cy.get('#payment-info').type('4111 1111 1111 1111');
        cy.get('#confirm-order').click();

        cy.url().should('include', '/checkout/confirmation');
        cy.get('#confirmation-message').should('contain', 'Thank you for your order');
    });

    it('should show an error if payment fails (edge case)', () => {
        cy.get('#cart').should('be.visible');
        cy.get('#proceed-to-checkout').click();

        cy.url().should('include', '/checkout/details');
        cy.get('#name').type('Jane Doe');
        cy.get('#address').type('456 Elm St');
        cy.get('#payment-info').type('1234 5678 9012 3456'); // Invalid card
        cy.get('#confirm-order').click();

        cy.url().should('include', '/checkout/details');
        cy.get('#error-message').should('contain', 'Payment failed, please try again');
    });
});
